    "definitions": {
        "file": {
            "oneOf": [
                {
                    "type": "object",
                    "required": [
                        "name",
                        "type",
                        "user",
                        "group"
                    ],
                    "properties": {
                        "name": {
                            "type": "string"
                        },
                        "type": {
                            "enum": [
                                "file",
                                "link",
                                "dir",
                                "remote_dir"
                            ]
