        "VRTparent": {
            "type": "object",
            "properties": {
                "id": {
                    "type": "string",
                    "pattern": "^[a-z_]*$"
                },
                "name": {
                    "type": "string",
                    "pattern": "^[ a-zA-Z0-9-+()/,.<]*$"
                },
                "type": {
                    "type": "string",
                    "enum": [
                        "category",
                        "subcategory"
                    ]
                },
                "children": {
                    "type": "array",
                    "items": {
                        "anyOf": [
                            {
                                "$ref": "#/definitions/VRTparent"
                            },
                            {
                                "$ref": "#/definitions/VRT"
                            }
                        ]
                    },
                    "minItems": 1
                }
            },
            "required": [
                "id",
                "name",
                "type",
                "children"
            ]
        }
    },
    "type": "object",
