        "metadata",
        "content"
    ],
    "properties": {
        "metadata": {
            "$ref": "#/definitions/VRTmetadata"
        },
        "content": {
            "type": "array",
            "items": {
                "anyOf": [
                    {
                        "$ref": "#/definitions/VRTparent"
                    },
                    {
                        "$ref": "#/definitions/VRT"
                    }
                ]
            }
        }
    }
